#requires -Version 7.0
[CmdletBinding()]param([string]$RetainedResultPath)
$ErrorActionPreference='Stop';$repo=Split-Path -Parent $PSScriptRoot;$out=Join-Path $repo ('.local/latency-03-1/clock-tests-'+[guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($out)|Out-Null
$fixture=Join-Path $repo 'tests/fixtures/Latency031ObservedClock.json';$originalVerified=$false
if($RetainedResultPath){if((Get-FileHash -Algorithm SHA256 -LiteralPath $RetainedResultPath).Hash.ToLowerInvariant()-cne'3585fc93e5dcff4984046cde5fa13815cc7d72e0c7c406d3392c7292845b8a32'){throw 'Retained original result drift; no substitution permitted.'};$old=Get-Content -LiteralPath $RetainedResultPath -Raw|ConvertFrom-Json;$expected=Get-Content -LiteralPath $fixture -Raw|ConvertFrom-Json;if($old.clocks.Count-ne6-or$old.timing.clockFrequency-ne$expected.qpcFrequency-or$old.timing.events[0].presentation.DeviceFrequency-ne$expected.deviceFrequency-or$old.StreamStartBeforeQpc-ne$expected.observedStreamStartBeforeQpc){throw 'Original clock metadata mismatch.'};for($i=0;$i-lt6;$i++){foreach($field in $old.clocks[$i].PSObject.Properties.Name){if($old.clocks[$i].$field-ne$expected.rows[$i].$field){throw 'Original clock observation mismatch.'}}};$originalVerified=$true}
$files=@('src/acoustics/host/Windows/PcmRing.cs','src/acoustics/host/Windows/PreparedTransientBus.cs','src/acoustics/host/Windows/Latency03PresentationClock.cs','tests/host/TestLatency031Clock.cs','tests/fixtures/Latency031ObservedClock.json','tools/Test-Latency031Clock.ps1');$pins=@($files|ForEach-Object{[ordered]@{file=$_;sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $repo $_)).Hash.ToLowerInvariant()}})
$compiler=Join-Path $env:WINDIR 'Microsoft.NET/Framework64/v4.0.30319/csc.exe';$exe=Join-Path $out 'Latency031Clock.Tests.exe'
& $compiler /nologo /optimize+ /unsafe+ /warnaserror+ /platform:x64 /r:System.Web.Extensions.dll ('/out:'+$exe) @($files|Where-Object{$_-like'*.cs'}|ForEach-Object{Join-Path $repo $_})
if($LASTEXITCODE-ne0){throw 'LATENCY-03.1 clock fixture compilation failed.'};$raw=@(& $exe $fixture $out);$raw|Set-Content -LiteralPath (Join-Path $out 'stdout.txt') -Encoding utf8;if($LASTEXITCODE-ne0){throw 'LATENCY-03.1 clock fixture failed; preserve failed output.'}
foreach($p in $pins){if((Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $repo $p.file)).Hash.ToLowerInvariant()-cne$p.sha256){throw 'Source changed during clock fixture.'}}
[ordered]@{schema=1;passed=$true;sourcePins=$pins;resultSha256=(Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $out 'result.json')).Hash.ToLowerInvariant();compilerSha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $compiler).Hash.ToLowerInvariant();retainedOriginalPrivatelyVerified=$originalVerified;endpointOpened=$false;endpointApiInvoked=$false;gameLaunched=$false;scope='Exact retained clock observations plus authored adverse clocks; no real endpoint query or playback.'}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $out 'validation.json') -Encoding utf8
Write-Output ('PASS LATENCY-03.1 pure clock fixtures; '+(Join-Path $out 'validation.json'))
